body {
  margin: 0;
}

.shell {
  min-height: 100vh;
  display: grid;
  place-items: start center;
  padding: 72px 24px;
  box-sizing: border-box;
}

.card {
  width: min(680px, 100%);
  background: white;
  border: 1px solid #dbe3ef;
  border-radius: 16px;
  box-shadow: 0 16px 45px rgb(38 55 84 / 10%);
  padding: 32px;
}

.eyebrow {
  color: #5b6b85;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1 {
  margin: 8px 0 28px;
}

.total-row {
  display: flex;
  justify-content: space-between;
  border-block: 1px solid #e3e9f2;
  padding: 20px 0;
  font-size: 20px;
}

button {
  margin-top: 22px;
  border: 0;
  border-radius: 8px;
  background: #2457d6;
  color: white;
  cursor: pointer;
  font: inherit;
  font-weight: 700;
  padding: 10px 14px;
}

.diagnostics {
  margin-top: 20px;
  border-radius: 10px;
  background: #111827;
  color: #dbeafe;
  padding: 16px;
}

.diagnostics h2 {
  margin-top: 0;
  font-size: 14px;
}

pre {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
