export function createApplicationServer(serviceOrigin) {
  return http.createServer(async (request, response) => {
    if (request.url.startsWith("/api/support-window")) {
      try {
        const upstream = await fetch(`${serviceOrigin}${request.url}`);
        const body = await upstream.text();
        response.writeHead(upstream.status, {
          "content-type": upstream.headers.get("content-type") ?? "application/json",
        });
        response.end(body);
      } catch (error) {
        response.writeHead(502, { "content-type": "application/json" });
        response.end(JSON.stringify({ error: "schedule service unavailable" }));
      }
      return;
    }

    const pathname = new URL(request.url, "http://app.invalid").pathname;
    const relative = pathname === "/" ? "index.html" : pathname.replace(/^\//, "");
    if (relative.includes("..")) {
      response.writeHead(400);
      response.end("bad request");
      return;
    }
    try {
      const body = await readFile(join(ROOT, relative));
      response.writeHead(200, { "content-type": MIME[extname(relative)] ?? "text/plain" });
      response.end(body);
    } catch {
      response.writeHead(404);
      response.end("not found");
    }
  });
}

